import * as rental from "host/rental";
import * as organizer from "host/organizer";
import * as strings from "std/string";

function asciiLower(text: string): string {
    let upper: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let lower: string = "abcdefghijklmnopqrstuvwxyz";
    let result: string = "";
    for (let character: string of text) {
        let replacement: string = character;
        for (let i: int = 0; i < 26; i = i + 1) {
            if (character === strings.substring(upper, i, i + 1)) {
                replacement = strings.substring(lower, i, i + 1);
            }
        }
        result = result + replacement;
    }
    return result;
}

function integerText(value: int): string {
    let digits: string = "0123456789";
    let remaining: int = value;
    let result: string = "";
    if (remaining === 0) {
        return "0";
    }
    while (remaining > 0) {
        let digit: int = remaining % 10;
        result = strings.substring(digits, digit, digit + 1) + result;
        remaining = remaining / 10;
    }
    return result;
}

function euroPrice(cents: int): string {
    let euros: int = cents / 100;
    let remainder: int = cents % 100;
    let fraction: string = integerText(remainder);
    if (remainder < 10) {
        fraction = "0" + fraction;
    }
    return "€" + integerText(euros) + "." + fraction;
}

function validQuantity(value: int): boolean {
    return value >= 1 && value <= 8;
}

function validBudget(value: int): boolean {
    return value >= 0 && value <= 100000;
}

function buildState(quantity: int, budget: int, search: string, sourceRows: RentalOption[], selectedId: string | null, loading: boolean, preparing: boolean, loaded: boolean, prepared: boolean, catalogueError: string, preparationError: string): State {
    let editable: boolean = !loading && !preparing;
    let valid: boolean = validQuantity(quantity) && validBudget(budget);
    let quantityError: string = "";
    let budgetError: string = "";
    if (!validQuantity(quantity)) {
        quantityError = "Quantity must be from 1 to 8.";
    }
    if (!validBudget(budget)) {
        budgetError = "Budget must be from 0 to 100000 cents.";
    }
    let rows: RentalOption[] = [];
    let hasSelection: boolean = false;
    for (let item: RentalOption of sourceRows) {
        let selected: boolean = false;
        if (selectedId !== null) {
            selected = item.id === selectedId;
        }
        if (selected) {
            hasSelection = true;
        }
        let copied: RentalOption = {
            id: item.id,
            title: item.title,
            detail: item.detail,
            price: item.price,
            meta: item.meta,
            totalCents: item.totalCents,
            selected: selected,
            enabled: editable && valid
        };
        rows[rows.length] = copied;
    }
    return {
        quantity: quantity,
        budget: budget,
        search: search,
        periodStart: "2026-10-10T16:00:00Z",
        periodEnd: "2026-10-10T22:00:00Z",
        rows: rows,
        selectedId: selectedId,
        loading: loading,
        preparing: preparing,
        loaded: loaded,
        prepared: prepared,
        catalogueError: catalogueError,
        preparationError: preparationError,
        quantityError: quantityError,
        budgetError: budgetError,
        editable: editable,
        canLoad: editable && valid,
        canPrepare: editable && valid && hasSelection && !prepared,
        empty: loaded && rows.length === 0
    };
}

function copyState(state: State): State {
    return buildState(state.quantity, state.budget, state.search, state.rows, state.selectedId, state.loading, state.preparing, state.loaded, state.prepared, state.catalogueError, state.preparationError);
}

export class RentalOption {
    id: string = "";
    title: string = "";
    detail: string = "";
    price: string = "";
    meta: string = "";
    totalCents: int = 0;
    selected: boolean = false;
    enabled: boolean = true;
}

export class State {
    quantity: int = 1;
    budget: int = 2000;
    search: string = "";
    periodStart: string = "2026-10-10T16:00:00Z";
    periodEnd: string = "2026-10-10T22:00:00Z";
    rows: RentalOption[] = [];
    selectedId: string | null = null;
    loading: boolean = false;
    preparing: boolean = false;
    loaded: boolean = false;
    prepared: boolean = false;
    catalogueError: string = "";
    preparationError: string = "";
    quantityError: string = "";
    budgetError: string = "";
    editable: boolean = true;
    canLoad: boolean = true;
    canPrepare: boolean = false;
    empty: boolean = false;
}

export class ChangeQuantity {
    value: int = 1;
}

export class ChangeBudget {
    value: int = 2000;
}

export class ChangeSearch {
    value: string = "";
}

export class PickOption {
    value: string = "";
}

export class LoadOptions {}

export class CatalogueFinished {
    rows: RentalOption[] = [];
    loaded: boolean = false;
    error: string = "";
}

export class PrepareForReview {}

export class PreparationFinished {
    success: boolean = false;
    error: string = "";
}

export function main(): null {
    return null;
}

export function initialState(): State {
    return {};
}

// @ui-update
export function changeQuantity(state: State, action: ChangeQuantity): State {
    if (!state.editable) {
        return copyState(state);
    }
    let rows: RentalOption[] = [];
    return buildState(action.value, state.budget, state.search, rows, null, false, false, false, false, "", "");
}

// @ui-update
export function changeBudget(state: State, action: ChangeBudget): State {
    if (!state.editable) {
        return copyState(state);
    }
    let rows: RentalOption[] = [];
    return buildState(state.quantity, action.value, state.search, rows, null, false, false, false, false, "", "");
}

// @ui-update
export function changeSearch(state: State, action: ChangeSearch): State {
    if (!state.editable) {
        return copyState(state);
    }
    let rows: RentalOption[] = [];
    return buildState(state.quantity, state.budget, action.value, rows, null, false, false, false, false, "", "");
}

// @ui-update
export function pickOption(state: State, action: PickOption): State {
    if (!state.editable) {
        return copyState(state);
    }
    for (let item: RentalOption of state.rows) {
        if (item.id === action.value && item.enabled) {
            return buildState(state.quantity, state.budget, state.search, state.rows, action.value, false, false, state.loaded, false, state.catalogueError, "");
        }
    }
    return copyState(state);
}

// @ui-update
export function requestCatalogue(state: State, action: LoadOptions): State {
    if (!state.canLoad) {
        return copyState(state);
    }
    let rows: RentalOption[] = [];
    return buildState(state.quantity, state.budget, state.search, rows, null, true, false, false, false, "", "");
}

// @ui-effect
export async function runLoad(state: State, action: LoadOptions): CatalogueFinished {
    if (!validQuantity(state.quantity) || !validBudget(state.budget) || state.preparing) {
        return { rows: [], loaded: false, error: "Enter a quantity from 1 to 8 and a valid budget before loading options." };
    }
    try {
        let records: table[] = await rental.equipment(state.periodStart, state.periodEnd);
        let rows: RentalOption[] = [];
        let search: string = asciiLower(strings.trim(state.search));
        for (let record: table of records) {
            let id: string = record.id;
            let title: string = record.name;
            let specification: string = record.specification;
            let cents: int = record.cents;
            let available: int = record.available;
            let searchable: string = asciiLower(title + " " + specification);
            let matches: boolean = strings.contains(searchable, "boom") && strings.contains(searchable, "stand");
            if (search !== "") {
                matches = matches && strings.contains(searchable, search);
            }
            if (matches && available >= state.quantity && cents >= 0) {
                // Bound the unit price before multiplying to avoid int overflow.
                if (cents <= state.budget / state.quantity) {
                    let total: int = cents * state.quantity;
                    let item: RentalOption = {
                        id: id,
                        title: title,
                        detail: specification,
                        price: euroPrice(total),
                        meta: "TOTAL for " + integerText(state.quantity) + " unit(s)",
                        totalCents: total,
                        selected: false,
                        enabled: true
                    };
                    rows[rows.length] = item;
                }
            }
        }
        return { rows: rows, loaded: true, error: "" };
    } catch (e) {
        return {
            rows: [],
            loaded: false,
            error: "Catalogue read failed or was denied. Restore the rental catalogue grant in the native permission surface, then use Load options to retry. " + e.message
        };
    }
}

// @ui-update
export function finishCatalogue(state: State, action: CatalogueFinished): State {
    return buildState(state.quantity, state.budget, state.search, action.rows, null, false, false, action.loaded, false, action.error, "");
}

// @ui-update
export function requestPreparation(state: State, action: PrepareForReview): State {
    if (!state.canPrepare) {
        return copyState(state);
    }
    return buildState(state.quantity, state.budget, state.search, state.rows, state.selectedId, false, true, state.loaded, false, state.catalogueError, "");
}

// @ui-effect
export async function runPrepare(state: State, action: PrepareForReview): PreparationFinished {
    if (!validQuantity(state.quantity) || !validBudget(state.budget) || state.loading || state.prepared) {
        return { success: false, error: "Select a qualifying option with valid inputs before preparing it." };
    }
    let selectedId: string | null = state.selectedId;
    if (selectedId === null) {
        return { success: false, error: "Select a qualifying option before preparing it." };
    }
    try {
        for (let item: RentalOption of state.rows) {
            let candidateId: string | null = state.selectedId;
            if (candidateId !== null) {
                if (item.id === candidateId) {
                    let detail: string = "Item " + item.id + ":" + integerText(state.quantity) + "; from " + state.periodStart + "; until " + state.periodEnd;
                    let result: table = await organizer.stage("rental", "host/rental", item.title, detail, item.price, state.periodEnd);
                    let staged: boolean = result.staged;
                    if (!staged) {
                        return { success: false, error: "Local preparation did not succeed. Retry Prepare for review; nothing has been reserved." };
                    }
                    return { success: true, error: "" };
                }
            } else {
                return { success: false, error: "Select a qualifying option before preparing it." };
            }
        }
        return { success: false, error: "The selected option is no longer in the shortlist. Load options again." };
    } catch (e) {
        return { success: false, error: "Local preparation failed or was denied. Restore the native grant if needed, then retry Prepare for review. " + e.message };
    }
}

// @ui-update
export function finishPreparation(state: State, action: PreparationFinished): State {
    return buildState(state.quantity, state.budget, state.search, state.rows, state.selectedId, false, false, state.loaded, action.success, state.catalogueError, action.error);
}

