import * as app from "./experience";
import * as ui from "./platform.dealui-pack";

// @ui-root
export view RentalShortlist(state: app.State): View {
    ui.Column() {
        ui.Hero(value: "Rental shortlist")
        ui.Text(value: "Requirement: Boom stand. Specification: Adjustable boom.")
        ui.Text(value: "Period start")
        ui.Text(value: state.periodStart)
        ui.Text(value: "Period end")
        ui.Text(value: state.periodEnd)
        ui.Notice(text: "Catalogue reads happen only when you choose Load options. Preparation is local and is not a reservation; native permission and confirmation remain outside this view.", tone: "info")
        ui.Card() {
            ui.IntField(value: state.quantity, label: "Quantity", minimum: 0, maximum: 9, step: 1, enabled: state.editable, supporting: "Only quantities from 1 to 8 are valid.", error: state.quantityError, onChange: action app.ChangeQuantity { value: payload }, accessibilityLabel: "Quantity")
            ui.IntField(value: state.budget, label: "Total budget in cents", minimum: 0, maximum: 100000, step: 100, enabled: state.editable, supporting: "Total budget for all requested units, from 0 to 100000 cents.", error: state.budgetError, onChange: action app.ChangeBudget { value: payload }, accessibilityLabel: "Budget")
            ui.SearchField(value: state.search, label: "Search", multiline: false, enabled: state.editable, supporting: "Optional name/specification substring. Spaces are trimmed and ASCII letters are matched without case.", error: "", onChange: action app.ChangeSearch { value: payload }, accessibilityLabel: "Search")
            ui.Button(text: "Load options", enabled: state.canLoad, onClick: action app.LoadOptions {}, accessibilityLabel: "Load options")
        }
        When(state.loading) {
            ui.Progress(label: "Loading")
        }
        When(state.catalogueError !== "") {
            ui.Failure(text: state.catalogueError, onRetry: action app.LoadOptions {}, accessibilityLabel: "Retry Load options after restoring the native catalogue grant")
        }
        ui.Section(title: "Qualifying options", summary: "Must match boom and stand, have enough available units, and fit the total budget. Prices shown are totals in euros.") {
            When(state.empty) {
                ui.Text(value: "No qualifying options")
            } Else {
                When(!state.loaded && !state.loading && state.catalogueError === "") {
                    ui.Text(value: "Set your inputs, then choose Load options to read the catalogue.")
                }
                ForEach(state.rows, item: app.RentalOption, key: item.id) {
                    ui.Option(value: item.id, title: item.title, detail: item.detail, price: item.price, meta: item.meta, selected: item.selected, enabled: item.enabled, onSelect: action app.PickOption { value: payload }, accessibilityLabel: item.title)
                }
            }
        }
        ui.Section(title: "Native review preparation", summary: "Prepare the selected option locally for native review. No booking or approval is performed.") {
            ui.Button(text: "Prepare for review", enabled: state.canPrepare, onClick: action app.PrepareForReview {}, accessibilityLabel: "Prepare for review")
            When(state.preparing) {
                ui.Progress(label: "Preparing for native review")
            }
            When(state.preparationError !== "") {
                ui.Failure(text: state.preparationError, onRetry: action app.PrepareForReview {}, accessibilityLabel: "Retry Prepare for review")
            }
            When(state.prepared) {
                ui.Notice(text: "Prepared for native review", tone: "info")
                ui.Text(value: "Your selection is preserved. Nothing has been reserved or approved.")
            }
        }
    }
}
